                  "password required to access the service.")
    import hashlib

    def authfunc(username, password):
        for u, p in mscolab_auth.allowed_users:
            if (u == username) and (p == hashlib.md5(password.encode('utf-8')).hexdigest()):
                return True
        return False

    @auth.verify_password
